menu_ResultMenu.calcTotalCoins = function() {
	var totalCoins = 0;
	if(!game_Game.current.isSurv) {
		totalCoins += game_Game.current.stats.cashEarned;
		if(game_Game.current.isWin) {
			var extraCoins = game_Game.getLvlExtra(game_Game.current.params.sectorFullNum) + game_Game.getClusterExtra(game_Game.current.params.clusterId);
			var bonusCoins = 0;
			switch(game_Game.current.params.realStarsCnt) {
			case 1:
				bonusCoins = extraCoins / 3.0 | 0;
				break;
			case 2:
				bonusCoins = extraCoins * 2.0 / 3.0 | 0;
				break;
			case 3:
				bonusCoins = extraCoins;
				break;
			default:
				bonusCoins = 0;
			}
			totalCoins += bonusCoins;
			var realExtraCoins = extraCoins * (game_Game.current.params.newOpened == true ? 1 : 0.5) | 0;
			totalCoins += realExtraCoins;
		}
	} else {
		var parsec = game_Game.current.getParsec();
		var survMult = parsec * game_G.survDistReward + 1;
		totalCoins = Math.round(game_Game.current.stats.cashEarned * survMult);
	}
	return totalCoins;
};
menu_ResultMenu.bringSectorCoinsToPlayer = function(rewarded) {
	if(rewarded == null) {
		rewarded = false;
	}
	var totalCoins = menu_ResultMenu.calcTotalCoins();
	var reward = rewarded ? "Rewarded" : "";
	game_G.logEventResource("source",game_Game.current.isSurv ? "survComplete" + reward : game_Game.current.isWin ? "gameComplete" + reward : "gameFail" + reward,"totalCoins",totalCoins,"coins");
	game_Player.addCoins(totalCoins);
	menu_Menu.current.topMenu.setCoinValue(game_Player.coins);
	menu_Menu.current.topMenu.setStarsValue(game_Player.getStarsCount());
	menu_Menu.current.topMenu.setScullsValue(game_Player.abyssSculls);
};
menu_ResultMenu.calcStars = function() {
	var numStars = 0;
	if(game_Game.current.params.sectorType == "bonus") {
		numStars = game_Game.getNumStarsBonus(game_Game.current.stats);
	} else if(game_Game.current.params.sectorType == "invaders") {
		numStars = game_Game.getNumStarsInvaders(game_Game.current.stats);
	} else {
		numStars = game_Game.getNumStars(game_Game.current.stats);
	}
	if(game_Game.current.isWin) {
		return numStars;
	} else {
		return 0;
	}
};
